required = {'python', 'sql', 'docker'}
alice = {'python', 'sql'}
bob = {'python', 'docker'}

for name, skills in [('alice', alice), ('bob', bob)]:
    missing = required - skills
    print(f'{name}: ready={not missing} missing={sorted(missing)}')

both = alice & bob
print('shared:', sorted(both))

